import{_ as o,c as n,o as t,aj as a}from"./chunks/framework.DyhGhnmO.js";const f=JSON.parse('{"title":"NeoNephos & Open Defense Cloud by BWI","description":"","frontmatter":{"title":"NeoNephos & Open Defense Cloud by BWI","date":"2026-10-16","banner":"assets/blog/20261016_open_defense_cloud_banner.svg","authors":["neonephos-team"],"tags":["2026","news"],"published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"BlogEntryThemeComponent"},"headers":[],"relativePath":"blog/20261016_OpenDefenseCloud_BWI.md","filePath":"blog/20261016_OpenDefenseCloud_BWI.md"}'),s={name:"blog/20261016_OpenDefenseCloud_BWI.md"};function r(i,e,l,d,p,h){return t(),n("div",null,e[0]||(e[0]=[a('<h1 id="neonephos-open-defense-cloud-by-bwi" tabindex="-1">NeoNephos &amp; Open Defense Cloud by BWI <a class="header-anchor" href="#neonephos-open-defense-cloud-by-bwi" aria-label="Permalink to &quot;NeoNephos &amp; Open Defense Cloud by BWI&quot;">​</a></h1><h2 id="neonephos-open-defense-cloud" tabindex="-1">NeoNephos &amp; Open Defense Cloud <a class="header-anchor" href="#neonephos-open-defense-cloud" aria-label="Permalink to &quot;NeoNephos &amp; Open Defense Cloud&quot;">​</a></h2><p>Software solutions suitable for the German Armed Forces are expected to perform reliably under a plethora of potential adverse conditions, starting from nodes intermittently dropping out to completely air-gapped scenarios. To deal with these increased demands for military applications, the BWI is integrating off-the-shelf open source components into the Open Defense Cloud, which is one of three key layers of the &quot;Bundeswehr&#39;s private cloud&quot; (pCloudBw). BWI joined the NeoNephos Foundation in the beginning of this year, and works closely with the Bundeswehr and outside partners through the Foundation.</p><p>The ODC itself is designed to be secure, sovereign, and mobile, able to process classified data, and built entirely on open-source software. Cloud computing here means rolling out applications and infrastructure quickly and at scale, with faster software updates and fewer failures. It’s the foundation to enable the Bundeswehr’s shift to Software Defined Defense (SDD) and the Modular Open Systems Approach (MOSA). The Bundeswehr will use the ODC via BWI-provided cloud infrastructure for IT services both at home and on deployments, taking a multicloud approach (several stacks, not one) to avoid vendor lock-in and stay interoperable with NATO. The ODC is one of three stacks within the Bundeswehr&#39;s “private cloud” (pCloudBw).</p><p><a href="https://www.bwi.de/magazin/artikel/bwi-realisiert-open-defense-cloud-fuer-die-bundeswehr" target="_blank" rel="noreferrer"><strong>What the ODC actually looks like in the field is covered in the original Blog Post by BWI</strong></a></p>',5)]))}const c=o(s,[["render",r]]);export{f as __pageData,c as default};
